            bc=any(a<i<b for a,b in zip(col_m,col_m[1:]))
            exp=3 if (br or bc) else 5
        if O[i][j]!=exp: bad.append((i,j,I[i][j],O[i][j],exp))
print("demo3 pair-rule(min=9) mismatches:",len(bad),bad[:10])

